-- LSPFI Master Data Dump (Schema, Parameters, Sequences, Units, KUK)
SET FOREIGN_KEY_CHECKS=0;

-- 1. ParameterBnsp
CREATE TABLE IF NOT EXISTS ParameterBnsp (
  id INT AUTO_INCREMENT PRIMARY KEY,
  kategori VARCHAR(50) NOT NULL,
  kode VARCHAR(50) NOT NULL,
  label VARCHAR(255) NOT NULL,
  parent_kode VARCHAR(50) DEFAULT NULL,
  KEY idx_kategori (kategori)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;


-- 2. Skema
CREATE TABLE IF NOT EXISTS Skema (
  id INT AUTO_INCREMENT PRIMARY KEY,
  kode_skema VARCHAR(100) DEFAULT NULL,
  nama_skema VARCHAR(255) NOT NULL,
  jenjang INT NOT NULL,
  kode_sektor VARCHAR(50) DEFAULT NULL,
  kode_profesi VARCHAR(50) DEFAULT NULL,
  status VARCHAR(20) DEFAULT 'Aktif'
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;


-- 3. UnitKompetensi
CREATE TABLE IF NOT EXISTS UnitKompetensi (
  id INT AUTO_INCREMENT PRIMARY KEY,
  skema_id INT NOT NULL,
  kode_unit VARCHAR(100) NOT NULL,
  judul_unit TEXT NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;


-- 4. ElemenKompetensi
CREATE TABLE IF NOT EXISTS ElemenKompetensi (
  id INT AUTO_INCREMENT PRIMARY KEY,
  unit_kompetensi_id INT NOT NULL,
  urutan_elemen INT NOT NULL,
  nama_elemen TEXT NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;


-- 5. KriteriaUnjukKerja
CREATE TABLE IF NOT EXISTS KriteriaUnjukKerja (
  id INT AUTO_INCREMENT PRIMARY KEY,
  elemen_kompetensi_id INT NOT NULL,
  urutan_kuk VARCHAR(20) NOT NULL,
  pernyataan_kuk TEXT NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;


-- 6. Sequences
CREATE TABLE IF NOT EXISTS RegistrationSequence (
  id INT AUTO_INCREMENT PRIMARY KEY,
  year INT NOT NULL,
  skema_id INT NOT NULL,
  last_seq INT DEFAULT 0,
  UNIQUE KEY year_skema (year, skema_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;


CREATE TABLE IF NOT EXISTS CertificateSequence (
  id INT AUTO_INCREMENT PRIMARY KEY,
  year INT NOT NULL,
  skema_id INT NOT NULL,
  last_seq INT DEFAULT 0,
  UNIQUE KEY year_skema (year, skema_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;


SET FOREIGN_KEY_CHECKS=1;
